begin;
create table public.rental_financial_closed_periods (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete restrict, tenancy_id uuid not null references public.rental_tenancies(id) on delete restrict, period_start date not null, period_end date not null, status text not null default 'closed' check(status in ('closed','reopened')), reason text not null check(length(btrim(reason))>0), closed_by uuid not null references auth.users(id) on delete restrict, closed_at timestamptz not null default now(), check(period_end>=period_start), unique(tenancy_id,period_start,period_end));
create table public.rental_financial_correction_requests (id uuid primary key default gen_random_uuid(), organisation_id uuid not null references public.organisations(id) on delete restrict, tenancy_id uuid not null references public.rental_tenancies(id) on delete restrict, correction_kind text not null check(correction_kind in ('adjustment','payment_reversal','adjustment_reversal')), adjustment_type text not null check(adjustment_type in ('debit','credit')), amount numeric(14,2) not null check(amount>0), effective_date date not null, reason text not null check(length(btrim(reason))>0), original_payment_id uuid references public.rental_financial_payments(id) on delete restrict, original_adjustment_id uuid references public.rental_financial_adjustments(id) on delete restrict, status text not null default 'pending' check(status in ('pending','applied','rejected')), requested_by uuid not null references auth.users(id) on delete restrict, requested_at timestamptz not null default now(), approved_by uuid references auth.users(id) on delete restrict, approved_at timestamptz, rejection_reason text, applied_adjustment_id uuid unique references public.rental_financial_adjustments(id) on delete restrict, check((correction_kind='adjustment' and original_payment_id is null and original_adjustment_id is null) or (correction_kind='payment_reversal' and original_payment_id is not null and original_adjustment_id is null) or (correction_kind='adjustment_reversal' and original_payment_id is null and original_adjustment_id is not null)));
create index rental_financial_correction_requests_tenancy_idx on public.rental_financial_correction_requests(tenancy_id,requested_at desc);
create unique index rental_financial_payment_reversal_once_idx on public.rental_financial_correction_requests(original_payment_id) where correction_kind='payment_reversal' and status in ('pending','applied');
create unique index rental_financial_adjustment_reversal_once_idx on public.rental_financial_correction_requests(original_adjustment_id) where correction_kind='adjustment_reversal' and status in ('pending','applied');
alter table public.rental_financial_adjustments add column correction_request_id uuid unique references public.rental_financial_correction_requests(id) on delete restrict;
alter table public.rental_financial_closed_periods enable row level security; alter table public.rental_financial_correction_requests enable row level security; revoke all on public.rental_financial_closed_periods,public.rental_financial_correction_requests from anon,authenticated; grant select on public.rental_financial_closed_periods,public.rental_financial_correction_requests to authenticated;
create policy rental_financial_closed_periods_staff_read on public.rental_financial_closed_periods for select to authenticated using(exists(select 1 from public.rental_tenancies t join public.rental_properties p on p.id=t.property_id where t.id=tenancy_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
create policy rental_financial_corrections_staff_read on public.rental_financial_correction_requests for select to authenticated using(exists(select 1 from public.rental_tenancies t join public.rental_properties p on p.id=t.property_id where t.id=tenancy_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
create or replace function public.rental_financial_manager_authorized(p_org uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and public.bridge_membership_role(p_org) in ('owner','principal','director','partner','admin','super_admin','manager','hq_manager','branch_manager')$$;
create or replace function public.rental_financial_period_is_closed(p_tenancy uuid,p_date date) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.rental_financial_closed_periods x where x.tenancy_id=p_tenancy and x.status='closed' and p_date between x.period_start and x.period_end)$$;
create or replace function public.rental_request_financial_adjustment(p_tenancy uuid,p_type text,p_amount numeric,p_date date,p_reason text) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.rental_tenancies%rowtype; rid uuid; begin if auth.uid() is null or p_type not in ('debit','credit') or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or p_date is null or length(btrim(coalesce(p_reason,'')))=0 then raise exception 'A valid adjustment type, amount, effective date and reason are required'; end if; select * into t from public.rental_tenancies where id=p_tenancy for update; if not found or not exists(select 1 from public.rental_properties p where p.id=t.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'You are not authorized for this tenancy'; end if; if public.rental_financial_period_is_closed(t.id,p_date) then raise exception 'The financial period is closed'; end if; insert into public.rental_financial_correction_requests(organisation_id,tenancy_id,correction_kind,adjustment_type,amount,effective_date,reason,requested_by) values(t.organisation_id,t.id,'adjustment',p_type,p_amount,p_date,btrim(p_reason),auth.uid()) returning id into rid; return jsonb_build_object('correction_id',rid,'status','pending'); end$$;
create or replace function public.rental_request_payment_reversal(p_payment uuid,p_date date,p_reason text) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.rental_financial_payments%rowtype; rid uuid; begin if auth.uid() is null or p_date is null or length(btrim(coalesce(p_reason,'')))=0 then raise exception 'An effective date and reason are required'; end if; select * into r from public.rental_financial_payments where id=p_payment for update; if not found or not exists(select 1 from public.rental_tenancies t join public.rental_properties p on p.id=t.property_id where t.id=r.tenancy_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'You are not authorized for this payment'; end if; if public.rental_financial_period_is_closed(r.tenancy_id,p_date) then raise exception 'The financial period is closed'; end if; insert into public.rental_financial_correction_requests(organisation_id,tenancy_id,correction_kind,adjustment_type,amount,effective_date,reason,original_payment_id,requested_by) values(r.organisation_id,r.tenancy_id,'payment_reversal','debit',r.amount,p_date,btrim(p_reason),r.id,auth.uid()) returning id into rid; return jsonb_build_object('correction_id',rid,'status','pending','amount',r.amount); end$$;
create or replace function public.rental_approve_financial_correction(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.rental_financial_correction_requests%rowtype; aid uuid; begin if auth.uid() is null then raise exception 'Authentication is required'; end if; select * into r from public.rental_financial_correction_requests where id=p_id for update; if not found then raise exception 'Correction request not found'; end if; if r.status<>'pending' then raise exception 'This correction request has already been resolved'; end if; if r.requested_by=auth.uid() then raise exception 'A different authorised manager must approve this correction'; end if; if not public.rental_financial_manager_authorized(r.organisation_id) then raise exception 'Manager approval is required'; end if; if public.rental_financial_period_is_closed(r.tenancy_id,r.effective_date) then raise exception 'The financial period is closed'; end if; insert into public.rental_financial_adjustments(organisation_id,tenancy_id,currency_code,adjustment_type,effective_date,amount,reason,reversal_of_adjustment_id,created_by,correction_request_id) values(r.organisation_id,r.tenancy_id,'ZAR',r.adjustment_type,r.effective_date,r.amount,r.reason,case when r.correction_kind='adjustment_reversal' then r.original_adjustment_id else null end,auth.uid(),r.id) returning id into aid; update public.rental_financial_correction_requests set status='applied',approved_by=auth.uid(),approved_at=now(),applied_adjustment_id=aid where id=r.id; return jsonb_build_object('correction_id',r.id,'status','applied','adjustment_id',aid,'adjustment_type',r.adjustment_type,'amount',r.amount); end$$;
revoke all on function public.rental_financial_manager_authorized(uuid),public.rental_financial_period_is_closed(uuid,date) from public,anon,authenticated; revoke execute on function public.rental_request_financial_adjustment(uuid,text,numeric,date,text),public.rental_request_payment_reversal(uuid,date,text),public.rental_approve_financial_correction(uuid) from public,anon; grant execute on function public.rental_request_financial_adjustment(uuid,text,numeric,date,text),public.rental_request_payment_reversal(uuid,date,text),public.rental_approve_financial_correction(uuid) to authenticated; commit;;
